function Assert-Exact([string]$Name,$Actual,$Expected){if($null -eq $Actual -and $null -eq $Expected){return};if($null -eq $Actual -or $null -eq $Expected -or $Actual -cne $Expected){throw "Bob Tin machine-matrix $Name differs. Observed '$Actual'; expected '$Expected'."}}
function Assert-Properties([string]$Name,$Object,[string[]]$Expected){if($null -eq $Object){throw "Bob Tin machine-matrix $Name is absent."};$actual=@($Object.PSObject.Properties.Name|Sort-Object);$wanted=@($Expected|Sort-Object);if(($actual -join "`n") -cne ($wanted -join "`n")){throw "Bob Tin machine-matrix $Name properties differ."}}
function Assert-StringArray([string]$Name,$Actual,[string[]]$Expected){$values=@($Actual|ForEach-Object{[string]$_});if(($values -join "`n") -cne ($Expected -join "`n")){throw "Bob Tin machine-matrix $Name differs."}}
function Assert-Entry([string]$Name,$Entry,[string]$Type,[string]$Item,[int]$Amount){Assert-Properties $Name $Entry @('type','name','amount');Assert-Exact "$Name.type" $Entry.type $Type;Assert-Exact "$Name.name" $Entry.name $Item;Assert-Exact "$Name.amount" $Entry.amount $Amount}
function Get-MatrixObservation([string]$Text,[string]$Stage){$matches=[regex]::Matches($Text,"\[mir-bob-tin-machine-matrix\] $Stage JSON (?<json>\{[^\r\n]+\})");if($matches.Count -ne 1){throw "Bob Tin machine-matrix requires exactly one $Stage JSON log; observed $($matches.Count)."};try{return $matches[0].Groups['json'].Value|ConvertFrom-Json -ErrorAction Stop}catch{throw "Bob Tin machine-matrix $Stage JSON is invalid: $($_.Exception.Message)"}}
function Assert-MatrixMachine([string]$Name,$Actual,$Expected,[bool]$Runtime){$properties=@('name','entity_type','place_item','energy_type','crafting_categories');if($Runtime){$properties+=,'levels'};Assert-Properties $Name $Actual $properties;foreach($property in @('name','entity_type','place_item','energy_type')){Assert-Exact "$Name.$property" $Actual.$property $Expected.$property};Assert-StringArray "$Name.crafting_categories" $Actual.crafting_categories @($Expected.crafting_categories);if($Runtime){if(@($Actual.levels).Count -ne @($script:record.production.levels).Count){throw "$Name runtime level count differs."};for($index=0;$index -lt @($script:record.production.levels).Count;$index++){$actualLevel=@($Actual.levels)[$index];$expectedLevel=@($script:record.production.levels)[$index];Assert-Properties "$Name.levels[$index]" $actualLevel @('completed_level','input_ore','input_exhausted','output','bonus','output_drain_observed');Assert-Exact "$Name.levels[$index].completed_level" $actualLevel.completed_level $expectedLevel.completed_level;Assert-Exact "$Name.levels[$index].input_ore" $actualLevel.input_ore $script:record.production.input_ore_per_machine_per_level;Assert-Exact "$Name.levels[$index].input_exhausted" $actualLevel.input_exhausted $script:record.production.requires_input_exhaustion;Assert-Exact "$Name.levels[$index].output" $actualLevel.output $expectedLevel.expected_output;Assert-Exact "$Name.levels[$index].bonus" $actualLevel.bonus $expectedLevel.expected_bonus;Assert-Exact "$Name.levels[$index].output_drain_observed" $actualLevel.output_drain_observed $script:record.production.output_drain_observed}}}
function Assert-MatrixData($Observation,$Dossier){Assert-Properties observed.data $Observation @('recipe','category','owner_count','effect_change','machines','unadmitted_matching_entities');Assert-Exact observed.data.recipe $Observation.recipe $Dossier.route.recipe;Assert-Exact observed.data.category $Observation.category $Dossier.route.category;Assert-Exact observed.data.owner_count $Observation.owner_count $Dossier.mir_owner.exact_owner_count;Assert-Exact observed.data.effect_change $Observation.effect_change $Dossier.mir_owner.effect_change_per_completed_level;Assert-StringArray observed.data.unadmitted_matching_entities $Observation.unadmitted_matching_entities @($Dossier.machine_selection.expected_unadmitted_matching_entities);if(@($Observation.machines).Count -ne @($Dossier.machine_selection.machines).Count){throw 'Bob Tin machine-matrix data machine count differs.'};for($index=0;$index -lt @($Dossier.machine_selection.machines).Count;$index++){Assert-MatrixMachine "observed.data.machines[$index]" @($Observation.machines)[$index] @($Dossier.machine_selection.machines)[$index] $false}}
function Assert-MatrixRuntime($Observation,$Dossier){Assert-Properties observed.runtime $Observation @('raw_direct','mirset1_imported','effective','no_level_4','input_ore_per_machine_per_level','machines');Assert-Exact observed.runtime.raw_direct $Observation.raw_direct $Dossier.cap_transport.raw_direct_max_level;Assert-Exact observed.runtime.mirset1_imported $Observation.mirset1_imported $Dossier.cap_transport.mirset1_imported_max_level;Assert-Exact observed.runtime.effective $Observation.effective $Dossier.cap_transport.effective_max_level;Assert-Exact observed.runtime.no_level_4 $Observation.no_level_4 $Dossier.cap_transport.no_level_4;Assert-Exact observed.runtime.input_ore $Observation.input_ore_per_machine_per_level $Dossier.production.input_ore_per_machine_per_level;if(@($Observation.machines).Count -ne @($Dossier.machine_selection.machines).Count){throw 'Bob Tin machine-matrix runtime machine count differs.'};for($index=0;$index -lt @($Dossier.machine_selection.machines).Count;$index++){Assert-MatrixMachine "observed.runtime.machines[$index]" @($Observation.machines)[$index] @($Dossier.machine_selection.machines)[$index] $true}}
function Assert-MatrixDriftControls($Dossier){
  $data=[pscustomobject]@{recipe=$Dossier.route.recipe;category=$Dossier.route.category;owner_count=1;effect_change=0.02;machines=@($Dossier.machine_selection.machines|ForEach-Object{$_|ConvertTo-Json -Depth 6|ConvertFrom-Json});unadmitted_matching_entities=@()}
  $data.machines[1].energy_type='steam';$caught=$false;try{Assert-MatrixData $data $Dossier}catch{$caught=$true};if(-not $caught){throw 'Bob Tin machine-matrix data-stage drift control was accepted.'}
  $runtimeMachines=@()
  foreach($machine in @($Dossier.machine_selection.machines)){
    $levels=@()
    foreach($level in @($Dossier.production.levels)){$levels += [pscustomobject]@{completed_level=$level.completed_level;input_ore=100;input_exhausted=$true;output=$level.expected_output;bonus=$level.expected_bonus;output_drain_observed=$true}}
    $runtimeMachines += [pscustomobject]@{name=$machine.name;entity_type=$machine.entity_type;place_item=$machine.place_item;energy_type=$machine.energy_type;crafting_categories=@($machine.crafting_categories);levels=$levels}
  }
  $runtime=[pscustomobject]@{raw_direct=2;mirset1_imported=3;effective=3;no_level_4=$true;input_ore_per_machine_per_level=100;machines=$runtimeMachines}
  $runtime.machines[3].levels[2].output=105;$caught=$false;try{Assert-MatrixRuntime $runtime $Dossier}catch{$caught=$true};if(-not $caught){throw 'Bob Tin machine-matrix runtime dynamic drift control was accepted.'}
  $dataSource=Get-Content -Raw -LiteralPath (Join-Path $script:fixture 'data-final-fixes.lua');$controlSource=Get-Content -Raw -LiteralPath (Join-Path $script:fixture 'control.lua')
  foreach($sentinel in @('data.raw[entity_type]','item.place_result == name','#unadmitted ~= 0')){if(-not $dataSource.Contains($sentinel)){throw "Bob Tin machine-matrix data source sentinel is absent: $sentinel"}}
  foreach($sentinel in @('get_inventory(defines.inventory.crafter_output)','entity.energy = 1000000000','output.remove')){if(-not $controlSource.Contains($sentinel)){throw "Bob Tin machine-matrix runtime source sentinel is absent: $sentinel"}}
}

