if(@($record.official_mod_closure).Count -ne 5){throw 'Bob Tin machine-matrix official closure count differs.'};$expectedOfficial=@(@{name='base';enabled=$true},@{name='elevated-rails';enabled=$false},@{name='quality';enabled=$false},@{name='recycler';enabled=$false},@{name='space-age';enabled=$false});for($index=0;$index -lt 5;$index++){Assert-Properties "official_mod_closure[$index]" @($record.official_mod_closure)[$index] @('name','enabled');Assert-Exact "official_mod_closure[$index].name" @($record.official_mod_closure)[$index].name $expectedOfficial[$index].name;Assert-Exact "official_mod_closure[$index].enabled" @($record.official_mod_closure)[$index].enabled $expectedOfficial[$index].enabled}
Assert-Properties route $record.route @('recipe','category','input','output','allow_productivity','auto_recycle');Assert-Exact route.recipe $record.route.recipe 'bob-tin-plate';Assert-Exact route.category $record.route.category 'smelting';Assert-Entry route.input $record.route.input item bob-tin-ore 1;Assert-Entry route.output $record.route.output item bob-tin-plate 1;Assert-Exact route.productivity $record.route.allow_productivity $true;Assert-Exact route.recycle $record.route.auto_recycle $false
Assert-Properties mir_owner $record.mir_owner @('stream_key','technology','effect_type','effect_recipe','effect_change_per_completed_level','exact_owner_count','prototype_max_level');Assert-Exact owner.stream $record.mir_owner.stream_key 'research_material_tin';Assert-Exact owner.technology $record.mir_owner.technology 'recipe-prod-research_material_tin-1';Assert-Exact owner.type $record.mir_owner.effect_type 'change-recipe-productivity';Assert-Exact owner.recipe $record.mir_owner.effect_recipe 'bob-tin-plate';Assert-Exact owner.change $record.mir_owner.effect_change_per_completed_level 0.02;Assert-Exact owner.count $record.mir_owner.exact_owner_count 1;Assert-Exact owner.max $record.mir_owner.prototype_max_level 'infinite'
Assert-Properties selection $record.machine_selection @('entity_types_scanned','required_crafting_category','required_place_item_rule','supported_runtime_energy_types','runtime_category_validation_rule','expected_unadmitted_matching_entities','machines');Assert-StringArray selection.types $record.machine_selection.entity_types_scanned @('assembling-machine','furnace');Assert-Exact selection.category $record.machine_selection.required_crafting_category 'smelting';Assert-Exact selection.place_rule $record.machine_selection.required_place_item_rule 'item-place-result-equals-entity-name';Assert-StringArray selection.energy $record.machine_selection.supported_runtime_energy_types @('burner','electric');Assert-Exact selection.runtime_category_validation_rule $record.machine_selection.runtime_category_validation_rule 'contains-exact-data-stage-categories-plus-entity-type-specific-recipe-assignment';Assert-StringArray selection.unadmitted $record.machine_selection.expected_unadmitted_matching_entities @();if(@($record.machine_selection.machines).Count -ne 6){throw 'Bob Tin machine-matrix must bind exactly six admitted machines.'};for($index=0;$index -lt 6;$index++){Assert-MatrixMachine "selection.machines[$index]" @($record.machine_selection.machines)[$index] @($record.machine_selection.machines)[$index] $false}
Assert-Properties energy $record.runtime_energy_provisioning @('burner','electric');Assert-Exact energy.burner $record.runtime_energy_provisioning.burner 'solid-fuel-in-crafter-fuel-inventory';Assert-Exact energy.electric $record.runtime_energy_provisioning.electric 'verified-per-tick-electric-buffer'
Assert-Properties recipe_assignment $record.runtime_recipe_assignment @('assembling-machine','furnace');Assert-Exact recipe_assignment.assembler $record.runtime_recipe_assignment.'assembling-machine' 'direct-set-recipe-bob-tin-plate';Assert-Exact recipe_assignment.furnace $record.runtime_recipe_assignment.furnace 'automatic-smelting-selection-validated-by-bob-tin-plate-output'
Assert-Properties caps $record.cap_transport @('raw_direct_max_level','mirset1_imported_max_level','effective_max_level','no_level_4');Assert-Exact caps.raw $record.cap_transport.raw_direct_max_level 2;Assert-Exact caps.imported $record.cap_transport.mirset1_imported_max_level 3;Assert-Exact caps.effective $record.cap_transport.effective_max_level 3;Assert-Exact caps.no4 $record.cap_transport.no_level_4 $true
Assert-Properties production $record.production @('input_ore_per_machine_per_level','output_drain_observed','requires_input_exhaustion','levels');Assert-Exact production.input $record.production.input_ore_per_machine_per_level 100;Assert-Exact production.drain $record.production.output_drain_observed $true;Assert-Exact production.exhaustion $record.production.requires_input_exhaustion $true;if(@($record.production.levels).Count -ne 4){throw 'Bob Tin machine-matrix production level count differs.'};for($index=0;$index -lt 4;$index++){$row=@($record.production.levels)[$index];Assert-Properties "production.levels[$index]" $row @('completed_level','expected_output','expected_bonus');Assert-Exact "production.levels[$index].completed_level" $row.completed_level $index;Assert-Exact "production.levels[$index].expected_output" $row.expected_output (100+2*$index);Assert-Exact "production.levels[$index].expected_bonus" $row.expected_bonus (2*$index)}
Assert-MatrixDriftControls $record

